package com.mahesh.empleave.leavebalance;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.leavetype.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.transaction.annotation.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;@RestController @RequestMapping("/api/leave-balances") @RequiredArgsConstructor public class LeaveBalanceController{private final LeaveBalanceRepository balances;private final BalanceTransactionRepository transactions;private final UserRepository users;private final LeaveTypeRepository types;private final AuditService audit;record Entitlement(@NotNull Long userId,@NotNull Long leaveTypeId,@NotNull @DecimalMin("0.00") @Digits(integer=5,fraction=2) BigDecimal totalDays,@NotBlank @Size(max=250) String reason){}@GetMapping("/my") List<ApiDtos.Balance> mine(Authentication a){return balances.findByUser(users.findByEmail(a.getName()).orElseThrow()).stream().map(ApiDtos::balance).toList();}@GetMapping("/employee/{id}") @PreAuthorize("hasRole('ADMIN')") List<ApiDtos.Balance> employeeBalances(@PathVariable Long id){return balances.findByUser(users.findById(id).orElseThrow()).stream().map(ApiDtos::balance).toList();}@GetMapping("/history") Page<ApiDtos.BalanceTxn> history(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(required=false) Long userId,@RequestParam(required=false) String type,@RequestParam(required=false) LocalDate startDate,@RequestParam(required=false) LocalDate endDate){if(startDate!=null&&endDate!=null&&endDate.isBefore(startDate))throw new IllegalArgumentException("endDate must not precede startDate");var actor=users.findByEmail(a.getName()).orElseThrow();if(userId!=null&&actor.getRole()!=Role.ADMIN)throw new SecurityException("Admin access required");var target=userId==null?actor:users.findById(userId).orElseThrow();var p=PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending());return transactions.filtered(target,type,startDate==null?null:startDate.atStartOfDay(),endDate==null?null:endDate.plusDays(1).atStartOfDay(),p).map(ApiDtos::transaction);}@PutMapping @PreAuthorize("hasRole('ADMIN')") @Transactional ApiDtos.Balance upsert(Authentication a,@RequestBody @jakarta.validation.Valid Entitlement x){var u=users.findById(x.userId()).orElseThrow();var t=types.findById(x.leaveTypeId()).orElseThrow();var b=balances.findForUpdate(u,t).orElseGet(()->balances.save(new LeaveBalance(u,t,BigDecimal.ZERO)));var delta=x.totalDays().subtract(b.getRemainingDays());if(delta.signum()!=0){b.adjust(delta);transactions.save(new BalanceTransaction(b,null,delta,x.reason()));audit.log(users.findByEmail(a.getName()).orElseThrow(),"ENTITLEMENT_ADJUSTED","LEAVE_BALANCE",b.getId());}return ApiDtos.balance(b);}}
